16→    private val partyPattern = Regex("(?i)^\\[?(?:Пати|Party)]?\\s*>?\\s*.*?(\\S+):\\s*(.+)")
17→    private val pmPattern = Regex("(?i)^(?:От|From|To|Кому)\\s+(?:\\[.+?]\\s*)?(\\S+):\\s*(.+)|^\\[(\\S+)\\s*->\\s*\\S+]\\s*(.+)")
