21→    fun init() {
22→        ChatEventsManager.registerOutgoing { message ->
23→            // 1. Проверка макро-чека
24→            if (MacroCheck.isBlocked()) {
25→                if (MacroCheck.checkAnswer(message)) {
26→                    // Ответ верный, пропускаем сообщение (оно не отправится в чат, так как мы возвращаем true)
27→                    return@registerOutgoing true
28→                } else {
29→                    // Ответ неверный или не число, блокируем отправку
30→                    mc.player?.displayClientMessage(Component.literal("§c§l[MACRO] §fСначала решите пример в чате!"), false)
31→                    return@registerOutgoing true
32→                }
33→            }
34→
35→            // 2. Проверка мьюта
36→            if (ModerationManager.isLocalMuted()) {
37→                val data = ModerationManager.getLocalMuteData()
38→                val lowerMsg = message.lowercase()
39→
40→                // Разрешаем только команды (начинающиеся с /), но не команды пати и не ! команды
41→                val isCommand = lowerMsg.startsWith("/")
42→                val isPartyCommand = lowerMsg.startsWith("/pc") || 
43→                                    lowerMsg.startsWith("/party chat") || 
44→                                    lowerMsg.startsWith("/chat party")
45→                val isExclamationCommand = config.enabled && config.convertCommands && lowerMsg.startsWith("!")
46→
47→                if (!isCommand || isPartyCommand || isExclamationCommand) {
48→                    mc.player?.displayClientMessage(
49→                        Component.literal("§c§l[MUTE] §fВы не можете писать в чат, так как заблокированы модератором §e${data?.mod}\n§fПричина: §7${data?.reason}"),
50→                        false
51→                    )
52→                    return@registerOutgoing true
53→                }
54→            }
55→
56→            // 3. Конвертация команд
57→            if (config.enabled && config.convertCommands && message.startsWith("!")) {
58→                mc.player?.connection?.sendCommand("pc ${message.substring(1)}")
59→                true
60→            } else false
61→        }
62→
63→        var lastProcessedMessage = ""
64→        ChatEventsManager.registerIncoming { message ->
65→            if (config.enabled && message != lastProcessedMessage) {
66→                lastProcessedMessage = message
67→                when {
68→                    partyPattern.containsMatchIn(message) -> handlePartyMessage(message)
69→                    pmPattern.containsMatchIn(message) -> handlePrivateMessage(message)
70→                }
71→            }
72→        }
73→    }
