75→    private fun handlePartyMessage(message: String) {
76→        val match = partyPattern.find(message) ?: return
77→        val player = match.groupValues[1]
78→        val text = match.groupValues[2]
79→
80→
81→        if (text.contains("!")) handlePartyCommand(player, text)
82→    }
