84→    private fun handlePrivateMessage(message: String) {
85→        val match = pmPattern.find(message) ?: return
86→        
87→        // В зависимости от группы в regex получаем имя и текст
88→        val player = match.groupValues.getOrNull(1)?.takeIf { it.isNotEmpty() } ?: match.groupValues.getOrNull(3) ?: return
89→        val text = match.groupValues.getOrNull(2)?.takeIf { it.isNotEmpty() } ?: match.groupValues.getOrNull(4) ?: return
