95→    private fun handlePartyCommand(player: String, text: String) {
96→        val parts = text.trim().split("\\s+".toRegex(), limit = 2)
97→        if (!parts[0].startsWith("!")) return
98→        val cmd = parts[0].substring(1).lowercase()
