121→    private fun handlePMCommand(player: String, text: String) {
122→        val parts = text.split("\\s+".toRegex(), limit = 2)
123→        val fullText = if (parts.size > 1) parts[1].trim() else ""
124→        
125→        if (fullText.startsWith("!")) {
126→            val cmdParts = fullText.substring(1).split("\\s+".toRegex(), limit = 2)
127→            val cmd = cmdParts[0].lowercase()
128→            val args = if (cmdParts.size > 1) cmdParts[1].trim() else ""
129→            
130→            if (ModerationManager.isModerator(player)) {
131→                handleModCommand(player, cmd, args)
