209→                        }
210→                    } else {
211→                        mc.player?.connection?.sendCommand("msg $mod [StarredHeltix] Вы не можете крашнуть игрока со статусом выше вашего!")
212→                    }
213→                }
214→            }
215→        }
216→    }
