5→object MessageFilterManager {
6→    private val config get() = StarredHeltix.feature.chat.general.messageFilter
7→
8→    fun shouldAllowMessage(message: String): Boolean {
9→        if (!config.enabled || config.filters.isEmpty()) return true
10→        
11→        // Убираем цветовые коды для корректной фильтрации, если они есть
12→        val cleanMessage = message.replace(Regex("§[0-9a-fk-orA-FK-OR]"), "")
13→        val prefix = cleanMessage.substringBefore(':')
14→        
15→        return config.filters.none { filter ->
16→            val cleanFilter = filter.replace(Regex("§[0-9a-fk-orA-FK-OR]"), "").trim()
17→            if (cleanFilter.isEmpty()) return@none false
18→            
19→            // Проверяем: 
20→            // 1. Сообщение начинается с фильтра
21→            // 2. Фильтр содержится в префиксе (до первого двоеточия - обычно это отправитель)
22→            cleanMessage.startsWith(cleanFilter, ignoreCase = true) || 
23→            prefix.contains(cleanFilter, ignoreCase = true)
24→        }
25→    }
26→
27→    fun addFilter(filter: String) {
28→        if (filter.isNotEmpty() && !config.filters.contains(filter)) {
29→            config.filters.add(filter)
30→            StarredHeltix.configManager.saveConfig("filter-add")
31→        }
32→    }
33→
34→    fun removeFilter(filter: String) {
35→        if (config.filters.remove(filter)) {
36→            StarredHeltix.configManager.saveConfig("filter-remove")
37→        }
38→    }
39→}
